using System.Text.Json.Serialization;

namespace D3B.Diagnostic.Reporting;

/// <summary>Stable contradiction categories generated by the report producer.</summary>
public enum DiagnosticReportContradictionCode
{
    /// <summary>The carried type URL did not match.</summary>
    [JsonStringEnumMemberName("TYPE_URL_MISMATCH")]
    TypeUrlMismatch,
    /// <summary>The engine message did not name a schema message.</summary>
    [JsonStringEnumMemberName("MESSAGE_MISMATCH")]
    MessageMismatch,
    /// <summary>More than one analysis status was observed.</summary>
    [JsonStringEnumMemberName("MIXED_STATUS")]
    MixedStatus,
    /// <summary>More than one top-level structure was observed.</summary>
    [JsonStringEnumMemberName("SHAPE_VARIATION")]
    ShapeVariation,
    /// <summary>An engine field declaration differed from the schema.</summary>
    [JsonStringEnumMemberName("FIELD_DECLARATION_MISMATCH")]
    FieldDeclarationMismatch,
    /// <summary>The engine truncated nested detail.</summary>
    [JsonStringEnumMemberName("DETAIL_TRUNCATED")]
    DetailTruncated
}
